Method.Implementation:
Set tStatus = $$$OK
Try {
	If (pRequest.%IsA("IHC.EAI.Monitor.Message.Request")) {
		If (pRequest.Name = "MirrorStatus") {
			Set tStatus = ..MonitorMirrorStatus(pRequest,.pResponse)
			$$$ThrowOnError(tStatus)
		} Else {
			$$$ThrowStatus($$$ERROR($$$EnsErrRequestNotHandled, pRequest.Name))	
		}
	} Else {
		$$$ThrowStatus($$$ERROR($$$EnsErrRequestNotHandled, pRequest.%ClassName(1)))
	}
} Catch eException {
	Set tStatus = eException.AsStatus()
}
Quit tStatus

#Dim tResultSet As %SQL.StatementResult
#Dim tRequest As IHC.EAI.Monitor.Message.Request
#Dim tResponse As IHC.EAI.Monitor.Message.Response
	
Set tStatus = $$$OK
Try {
	Set pResponse = ##class(IHC.EAI.Monitor.Message.Response).%New()
	
	// Determine environment
	Set tStatus = ..GetEnvironment(.tEnvironment,.tInstanceType,.tInstanceName)
	$$$ThrowOnError(tStatus)
	
	// Get the data using each virutal ip instance in this environment
	Set tQuery = 	"SELECT VirtualHost,VirtualPort " _
					"FROM IHC_EAI_System_Data.Instance " _ 
					"WHERE EnvironmentType = ? AND NodeType = 'INTERFACE' GROUP BY VirtualHost"
	Set tStatement = ##class(%SQL.Statement).%New()
	Set tStatus = tStatement.%Prepare(tQuery)
	$$$ThrowOnError(tStatus)
	Set tResultSet = tStatement.%Execute(tEnvironment)
	
	Set tNotifyList = ##class(%ListOfObjects).%New()
	While (tResultSet.%Next(.tStatus)) {
		$$$ThrowOnError(tStatus)
		
		Set tServer = tResultSet.%GetData(1)
		Set tPort = tResultSet.%GetData(2)
		
		Set tRequest = pRequest.%ConstructClone()
		Set tRequest.Command = "GET"
		Set tRequest.URL = ..StatusServiceURL
		Set tRequest.Server = tServer
		Set tRequest.Port = tPort
		
		Set tStatus = ..SendRequestSync(..TargetConfigName,tRequest,.tResponse)
		$$$ThrowOnError(tStatus)
		
		If ($$$IsdefObject(tResponse)) {
			If (tResponse.JSONStream '= "") {
				Set tStatus = ..ProcessMembers(tServer,tPort,tResponse.JSONStream,.tNotifyList)
				$$$ThrowOnError(tStatus)
					
			} Else {
				$$$ThrowStatus($$$ERROR($$$GeneralError,"JSON response stream does not exist"))
			}	
		} Else {
			$$$ThrowStatus($$$ERROR($$$GeneralError,"Mirror status response does not exist"))
		}
	}
	$$$ThrowOnError(tStatus)
	
	// Send a notification for all offenders
	Set tStatus = ..SendNotification(tNotifyList,tEnvironment)
	$$$ThrowOnError(tStatus)
} Catch eException {
	Set tStatus = eException.AsStatus()
}
Quit tStatus

	#Dim tMemberStatus As IHC.EAI.Monitor.Mirror.Data.MemberStatus

	Set tStatus = $$$OK
	Try {
		Set tStatus = ..JSONStreamToObjectArray(pStream,.tObjArray,,1)
		$$$ThrowOnError(tStatus)
		
		Set tCount = tObjArray
		For i=1:1:tCount {
			Set tResponseObj = tObjArray(i)
			
			If (tResponseObj.errorMessage = "") {
				Set tCurrentRole = tResponseObj.currentStatus
				// Process the member status
				If ($ZCONVERT(tCurrentRole,"U") '= "PRIMARY") {
					Set tMemberStatus = ..GetMemberStatus(pServer,pPort,.tStatus)
					$$$ThrowOnError(tStatus)
					
					Set tStatus = ..ProcessStatus(.tMemberStatus,tResponseObj,.pNotifyList)
					$$$ThrowOnError(tStatus)
				}
			} Else {
				// Process the error
				Set tMemberStatus = ..GetMemberStatus(pServer,pPort,.tStatus)
				$$$ThrowOnError(tStatus)
					
				Set tErrorMessage = tResponseObj.errorMessage
				
				/// Clear inaccurate info in event of HTTP error
				If (tErrorMessage [ "ErrHTTPStatus") {
					Set tMemberStatus.CurrentRole = ""
					Set tMemberStatus.DatabaseLatency = ""
					Set tMemberStatus.DatabaseTimeLatency = ""
					Set tMemberStatus.JournalLatency = ""
					Set tMemberStatus.JournalTimeLatency = ""
					Set tMemberStatus.MemberName = ""
					Set tMemberStatus.Status = "Down"	
				}
				
				Set tMemberStatus.Notes = tErrorMessage
				Set tStatus = tMemberStatus.%Save()
				$$$ThrowOnError(tStatus)
				
				Do pNotifyList.Insert(tMemberStatus)
			}
		}
	} Catch eException {
		Set tStatus = eException.AsStatus()
	}
	Quit tStatus

Set tStatus = $$$OK
Try {
	
	Set tMemberName = pMemberStatusExternal.memberName
	Set tDatabaseLatency = pMemberStatusExternal.databaseLatency
	Set tDatabaseTimeLatency = pMemberStatusExternal.databaseTimeLatency
	Set tJournalLatency = pMemberStatusExternal.journalLatency
	Set tJournalTimeLatency = pMemberStatusExternal.journalTimeLatency
	Set tCurrentStatus = pMemberStatusExternal.currentStatus
	Set tCurrentRole = pMemberStatusExternal.currentRole
	
	Set pMemberStatusLocal.MemberName = tMemberName
	Set pMemberStatusLocal.DatabaseLatency = tDatabaseLatency
	Set pMemberStatusLocal.JournalLatency = tJournalLatency
	Set pMemberStatusLocal.DatabaseTimeLatency = tDatabaseTimeLatency
	Set pMemberStatusLocal.JournalTimeLatency = tJournalTimeLatency
	Set pMemberStatusLocal.CurrentRole = tCurrentRole
	Set pMemberStatusLocal.Status = tCurrentStatus
	
	// If Trouble, Inactive, or Down, add to the notify list
	Set tNotifyOnBadStatus = 0,tNotifyOnDatabaseBackup = 0,tNotifyOnJournalFilesBackup = 0
	If (tCurrentStatus = "Trouble" || tCurrentStatus= "Inactive" || tCurrentStatus= "Down") {
		// Add to notify list
		
		If ($LENGTH(tDatabaseTimeLatency) > 0) {
			Set pMemberStatusLocal.Notes = tDatabaseTimeLatency
		} ElseIf ($LENGTH(tJournalTimeLatency) > 0) {
			Set pMemberStatusLocal.Notes = tDatabaseTimeLatency
		}
		Set tNotifyOnBadStatus = 1
		
	} Else {
		
		// Analysis - Database Latency
		If ((tDatabaseLatency [ "behind") && (tDatabaseLatency [ "file")) {
			Set tNumFilesBehind = +tDatabaseLatency
			If (tNumFilesBehind >= ..DatabaseLatencyMax) {
				Set tNotifyOnDatabaseBackup = 1
				Set pMemberStatusLocal.Notes = tDatabaseLatency
			}
		}	
		
		// Analysis - Journal file(s) reception latency
		If ((tJournalLatency [ "behind") && (tJournalLatency [ "file")) {
			Set tNumFilesBehind = +tJournalLatency
			If (tNumFilesBehind >= ..JournalFilesLatencyMax) {
				Set tNotifyOnJournalFilesBackup = 1
				If ($LENGTH(pMemberStatusLocal.Notes) > 0) {
					Set pMemberStatusLocal.Notes = pMemberStatus.Notes _ ", " _ tJournalLatency
				} Else {
					Set pMemberStatusLocal.Notes = tJournalLatency
				}
			}
		}
	}
	
	// Save for next round
	Set tStatus = pMemberStatusLocal.%Save()
	$$$ThrowOnError(tStatus)
	
	If ((tNotifyOnDatabaseBackup) || (tNotifyOnJournalFilesBackup) || (tNotifyOnBadStatus)) {
		Do pNotifyList.Insert(pMemberStatusLocal)
	}
} Catch eException {
	Set tStatus = eException.AsStatus()
}
Quit tStatus

#Dim tMirrorMember As IHC.EAI.Monitor.Mirror.Data.MemberStatus

Set tStatus = $$$OK
Try {
	Quit:(pNotifyList.Count() = 0)
	
	If (..TriggerAlert) {
		Set tAlertText = "Mirror latency alert."
		
		For i=1:1:pNotifyList.Count() {
			Set tMirrorMember = pNotifyList.GetAt(i)
			Set tVirtualServer = tMirrorMember.VirtualServer
			Set tVirtualPort = tMirrorMember.VirtualPort
			Set tName = tMirrorMember.MemberName
			Set tRole = tMirrorMember.CurrentRole
			Set tStatus = tMirrorMember.Status
			Set tNotes = tMirrorMember.Notes
			
			Set tAlertText = tAlertText _ $CHAR(13,10) _ $CHAR(13,10) _ 
									"Virtual Server/Port: " _ tVirtualServer _ "/" _ tVirtualPort _ $CHAR(13,10) _ 
									"Instance/Role: " _ tName _ "/" _ tRole _ $CHAR(13,10) _ 
									"Status:" _ tStatus _ $CHAR(13,10) _ 
									"Notes:" _ tNotes
		}
		
		Set tAlertRequest = ..CreateAPEAlert($$$EAIMirrorLatencyError,tAlertText,.tCreateAPEAlertStatus)
		$$$ThrowOnError(tCreateAPEAlertStatus)
		
		Set tStatus = ..SendAlert(tAlertRequest)
		$$$ThrowOnError(tStatus)
	}
	
	If ($LENGTH(..Recipient) > 0) {
		// Send an alert via email operation
		Set tRequest = ##class(IHC.EAI.Common.Message.EmailRequest).%New()
		
		// Add recipients
		For i=1:1:$LENGTH(..Recipient,",") {
			Set tRecipComma = $Piece(..Recipient,",",i)
			For j=1:1:$LENGTH(tRecipComma,";") {
				Set tRecip = $ZStrip($Piece(tRecipComma,";",j),"<>WC")
				If ("" '= tRecip) {
					Set tStatus = tRequest.To.Insert(tRecip)
					$$$ThrowOnError(tStatus)
				}
			}
			$$$ThrowOnError(tStatus)
		}
		
		Set tRequest.Subject = "Ensemble Mirror Journal Latency Issue - " _ pEnvironment
		Set tRequest.From = ..From
		
		// Build the message body html
		Set tBody = ##class(%Stream.GlobalCharacter).%New()
		Do tBody.Write("<!doctype html><html lang=""en""><head>")
		Do tBody.Write("<meta charset=""utf-8"" /><title>Mirror Member Monitor: Latency Status</title>")
		Do tBody.Write("<meta name=""description"" content=""EAI Mirror Monitor Latency Status"" />")
		Do tBody.Write("<meta name=""author"" content=""InterfaceSupport"" />")
		Do tBody.Write("<style>td,th {border: 1px solid #dddddd;text-align: left;padding: 8px;}</style>")
		Do tBody.Write("</head><body>")
		
		Do tBody.Write("<h1>Mirror Member Monitor: Latency Status</h1>")
		Do tBody.Write("<table><tr><th>Virtual Server/Port</th><th>Member Name</th><th>Role</th><th>Status</th><th>Notes</th></tr>")
		For i=1:1:pNotifyList.Count() {
			Set tMirrorMember = pNotifyList.GetAt(i)
			
			Do tBody.Write("<tr><td>" _ tMirrorMember.VirtualServer _ "/" _ tMirrorMember.VirtualPort _ "</td>")
			Do tBody.Write("<td>" _ tMirrorMember.MemberName _ "</td>")
			Do tBody.Write("<td>" _ tMirrorMember.CurrentRole _ "</td>")
			Do tBody.Write("<td>" _ tMirrorMember.Status _ "</td>")
			Do tBody.Write("<td>" _ tMirrorMember.Notes _ "</td></tr>")
		}
		Do tBody.Write("</table></body></html>")
		
		Do tBody.Rewind()
		Set tRequest.TextData = tBody
		
		Set tStatus = ..SendRequestSync(..EmailOperationTarget,tRequest,.tResponse)
		$$$ThrowOnError(tStatus)
	}
} Catch eException {
	Set tStatus = eException.AsStatus()
}
Quit tStatus

Set tAlertRequest = ##class(Ens.AlertRequest).%New()
Try {
	
	Set tAlertRequest.AlertText = pErrorCode _ " " _ pAlertText
	Set tAlertRequest.SourceConfigName = ..%ConfigName
	
} Catch eException {
	Set pStatus = eException.AsStatus()
}
Quit tAlertRequest

Set tMemberStatus = ""
Try {
	Set SQLCODE = "", tRecordId = ""
	&sql(SELECT %Id INTO :tRecordId FROM IHC_EAI_Monitor_Mirror_Data.MemberStatus WHERE VirtualServer = :pServer AND VirtualPort = :pPort)
	If ((SQLCODE '= 0) && (SQLCODE '= 100)) {
		$$$ThrowStatus($$$ERROR($$$GeneralError, "Failed to query mirror member data table."))	
	} Else {
		If (SQLCODE = 100) {
			Set tMemberStatus = ##class(IHC.EAI.Monitor.Mirror.Data.MemberStatus).%New()
			Set tMemberStatus.VirtualServer = pServer
			Set tMemberStatus.VirtualPort = pPort
			Set tMemberStatus.MonitorCreatedOn = $ZDT($H,3)
		} Else {
			Set tMemberStatus = ##class(IHC.EAI.Monitor.Mirror.Data.MemberStatus).%OpenId(tRecordId,,.pStatus)
			$$$ThrowOnError(pStatus)
			Set tMemberStatus.MonitorUpdatedOn = $ZDT($H,3)
		}
	}
} Catch eException {
	Set pStatus = eException.AsStatus()
}
Quit tMemberStatus
